1: #!/usr/bin/env node
2: /**
3:  * Cross-platform asset copy for build scripts (replaces `mkdir -p` + `cp` which
4:  * don't exist on Windows cmd.exe). Copies files matching simple patterns into a
5:  * dest dir, creating it recursively.
6:  *
7:  * Usage:
8:  *   node scripts/copy-assets.mjs <destDir> <srcGlobOrDir> [<srcGlobOrDir> ...]
9:  *
10:  * Each src arg is either:
11:  *   - a directory  → copied recursively into destDir (dir-to-dir)
12:  *   - a glob like  `src/foo/*.md` → every matching file copied flat into destDir
13:  *   - a plain file → copied into destDir
14:  *
15:  * Run from the package dir whose package.json invokes it (cwd-relative paths).
16:  */
17: import { cpSync, mkdirSync, readdirSync, statSync } from "node:fs";
18: import { basename, dirname, join } from "node:path";
19: 
20: const [, , destDir, ...srcs] = process.argv;
21: if (!destDir || srcs.length === 0) {
22:   console.error("usage: copy-assets.mjs <destDir> <src> [<src> ...]");
23:   process.exit(2);
24: }
25: 
26: mkdirSync(destDir, { recursive: true });
27: 
28: for (const src of srcs) {
29:   const star = src.indexOf("*");
30:   if (star === -1) {
31:     // plain file or directory
32:     let isDir = false;
33:     try {
34:       isDir = statSync(src).isDirectory();
35:     } catch {
36:       console.error(`copy-assets: source not found: ${src}`);
37:       process.exit(1);
38:     }
39:     // dir → dir/<name> (mirrors `cp -r dir destParent/`); file → destDir/<name>
40:     const target = join(destDir, basename(src));
41:     cpSync(src, target, { recursive: true });
42:   } else {
43:     // glob like "src/prompt/sections/*.md" — only a trailing "*.<ext>" segment
44:     const dir = dirname(src);
45:     const pat = basename(src); // e.g. "*.md"
46:     const ext = pat.startsWith("*") ? pat.slice(1) : pat; // ".md"
47:     let files = [];
48:     try {
49:       files = readdirSync(dir).filter((f) => f.endsWith(ext));
50:     } catch {
51:       console.error(`copy-assets: source dir not found: ${dir}`);
52:       process.exit(1);
53:     }
54:     if (files.length === 0) {
55:       console.error(`copy-assets: glob matched no files: ${src}`);
56:       process.exit(1);
57:     }
58:     for (const f of files) cpSync(join(dir, f), join(destDir, f));
59:   }
60: }
